SourceCode.Declaration:
/// <summary>
/// The <c>METBulkWorkflowWorkItemManagerSubTaskContract</c> class for sub task batch job.
/// </summary>
/// Added for CFR4 bulk approval AR invoice.
[DataContractAttribute]
class METBulkWorkflowWorkItemManagerSubTaskContract
{
    RefRecId                    startRefRecId;
    RefRecId                    endRefRecId;
    WorkflowComment             workflowComment;
    WorkflowWorkItemActionType  actionType;
    UserId                      userId;

}

Method.Source:
/// <summary>
/// Set the start recId of the thread.
/// </summary>
/// <param name = "_startRefRecId">Contains start recId.</param>
/// <returns>Return thread start RecId</returns>
[DataMember]
public RefRecId parmStartRefRecId(RefRecId _startRefRecId = startRefRecId)
{
    startRefRecId = _startRefRecId;

    return startRefRecId;
}

/// <summary>
/// Set the end recId of the thread.
/// </summary>
/// <param name = "_endRefRecId">Contains end recId.</param>
/// <returns>Return thread end RecId</returns>
[DataMember]
public RefRecId parmEndRefRecId(RefRecId _endRefRecId = endRefRecId)
{
    endRefRecId = _endRefRecId;

    return endRefRecId;
}

/// <summary>
/// Set the workflowcomment of the thread.
/// </summary>
/// <param name = "_workflowComment">Contains workflow comment.</param>
/// <returns>Return workflow comment.</returns>
[DataMember]
public WorkflowComment parmWorkFlowComment(WorkflowComment _workflowComment = workflowComment)
{
    workflowComment = _workflowComment;

    return workflowComment;
}

/// <summary>
/// Set the WorkflowWorkItemActionType of the thread.
/// </summary>
/// <param name = "_actionType">Contains WorkflowWorkItemActionType.</param>
/// <returns>Return WorkflowWorkItemActionType.</returns>
[DataMember]
public WorkflowWorkItemActionType parmWorkflowActionType(WorkflowWorkItemActionType _actionType = actionType)
{
    actionType = _actionType;

    return actionType;
}

/// <summary>
/// Gets or sets the userid.
/// </summary>
/// <param name="_userId">The userid to get reassigned.</param>
/// <returns>The userid.</returns>
[DataMember]
public UserId parmUserId(UserId _userId = userId)
{
    userId = _userId;

    return userId;
}
